 ImGui::BeginDisabled(serial_.connected||connecting_||detector_.busy||testWire_.is_open());
 if(button("Autodetect",ImVec2(130,32))){detector_.start();ImGui::OpenPopup("Autodetect");}ImGui::EndDisabled();ImGui::SameLine();
