 ImGui::BeginDisabled(detector_.busy||testWire_.is_open());if(button(serial_.connected||connecting_?"Disconnect":"Connect",ImVec2(100,32))){if(serial_.connected||connecting_)disconnect();else connect();focusTerminal_=true;}ImGui::EndDisabled();ImGui::SameLine();
 if(button("Setup",ImVec2(85,32)))ImGui::OpenPopup("Connection setup");ImGui::SameLine();
