  int mode=settings_.parity==1?1:0;ImGui::SetNextItemWidth(250);if(ImGui::Combo("Instrument",&mode,"8N1\0" "7E1 (software parity)\0")){settings_.parity=mode;settings_.bits=mode?7:8;}
  ImGui::Checkbox("DTR",&settings_.dtr);ImGui::SameLine();ImGui::Checkbox("RTS",&settings_.rts);ImGui::EndDisabled();
