void App::drawData(){title("Data & profiles",heading_);if(documents_.empty()){paragraph("Open a measurement file or capture an instrument session to inspect data here.");return;}ImGui::SetNextItemWidth(std::max(200.f,ImGui::GetContentRegionAvail().x-255));if(ImGui::BeginCombo("##dataset",documents_[document_].table.source.c_str())){for(size_t i=0;i<documents_.size();i++){ImGui::PushID(static_cast<int>(i));if(ImGui::Selectable(documents_[i].table.source.c_str(),document_==static_cast<int>(i))){document_=static_cast<int>(i);autoMap();}ImGui::PopID();}ImGui::EndCombo();}ImGui::SameLine();if(button("Export CSV"))saveData(selected()->csv(),L"Export measurements",L"csv");ImGui::SameLine();if(button("Close dataset")){documents_.erase(documents_.begin()+document_);document_=std::max(0,document_-1);autoMap();return;}Table& t=*selected();auto& doc=documents_[document_];ImGui::Text("%zu rows | %zu columns | %zu malformed rows skipped",t.rows.size(),t.columns.size(),t.rejected);
 if(ImGui::BeginTabBar("datatabs")){if(ImGui::BeginTabItem("Graph")){ImGui::SetNextItemWidth(195);columnPicker("X / depth",t,doc.x,true);ImGui::SameLine();ImGui::SetNextItemWidth(195);columnPicker("Measurement",t,doc.y);ImGui::SameLine();ImGui::Checkbox("Depth downward",&doc.profile);plot(t,doc.x,doc.y,doc.profile,ImVec2(ImGui::GetContentRegionAvail().x,std::max(190.f,ImGui::GetContentRegionAvail().y-85)));auto s=statistics(t,doc.y);ImGui::Text("Valid: %zu   Missing: %zu   Min: %s   Max: %s",s.valid,s.invalid,format(s.min).c_str(),format(s.max).c_str());ImGui::Text("Mean: %s   Standard deviation: %s",format(s.mean).c_str(),format(s.sd).c_str());ImGui::EndTabItem();}if(ImGui::BeginTabItem("Measurements")){grid(t,ImGui::GetContentRegionAvail().y);ImGui::EndTabItem();}if(ImGui::BeginTabItem("Multi-channel")){const char* fields[]={"T","S","C","P","OX","OT"};float w=(ImGui::GetContentRegionAvail().x-12)/2;int shown=0;for(auto f:fields){int c=t.column(f);if(c<0)continue;ImGui::PushID(f);plot(t,-1,c,false,ImVec2(w,190));ImGui::PopID();shown++;if(shown%2)ImGui::SameLine();}if(!shown)paragraph("Choose this file's custom channel names in the Graph tab.");ImGui::EndTabItem();}if(ImGui::BeginTabItem("Source notes")){for(auto& note:t.notes)paragraph(note.c_str());ImGui::EndTabItem();}ImGui::EndTabBar();}}
void App::drawUtilities(){title("Measurement utilities",heading_);muted("Preview a result, then keep it as a new dataset. Your source stays intact.");Table* t=selected();if(!t){paragraph("Open a dataset first.");return;}ImGui::Text("Source: %s",t->source.c_str());ImGui::SetNextItemWidth(360);if(ImGui::Combo("Tool",&utility_,"Oceanographic calculations (TEOS-10)\0Select / split rows\0Filter by value range\0Remove spikes (running median)\0Adjust values (gain + offset)\0Standard depths / pressure levels\0"))preview_.reset();ImGui::Separator();
 if(utility_==0){ImGui::SetNextItemWidth(260);columnPicker("Conductivity (mS/cm)",*t,calc_.conductivity,true);ImGui::SetNextItemWidth(260);columnPicker("Salinity (PSS-78), if no C",*t,calc_.salinity,true);ImGui::SetNextItemWidth(260);columnPicker("Temperature",*t,calc_.temperature);ImGui::SetNextItemWidth(260);columnPicker("Sea pressure (dbar)",*t,calc_.pressure);ImGui::SetNextItemWidth(260);columnPicker("Oxygen saturation (%)",*t,calc_.oxygen,true);ImGui::Checkbox("Input temperature is IPTS-68 (otherwise ITS-90)",&calc_.temperature68);ImGui::SetNextItemWidth(140);ImGui::InputDouble("Latitude",&latitude_,0,0,"%.5f");ImGui::SameLine();ImGui::SetNextItemWidth(140);ImGui::InputDouble("Longitude",&longitude_,0,0,"%.5f");ImGui::Checkbox("Station coordinates and input units confirmed",&locationConfirmed_);paragraph("Official GSW TEOS-10 routines. Oxygen assumes standard atmospheric pressure. Results may differ from legacy SD200W calculations.");}
 else if(utility_==1){ImGui::SetNextItemWidth(150);ImGui::InputInt("First row (1-based)",&rangeFirst_);ImGui::SetNextItemWidth(150);ImGui::InputInt("Last row (inclusive)",&rangeLast_);}
 else{ImGui::SetNextItemWidth(270);columnPicker(utility_==5?"Depth / sea pressure":"Column",*t,utilCol_);if(utility_==2){ImGui::InputDouble("Minimum",&minimum_);ImGui::InputDouble("Maximum",&maximum_);}if(utility_==3){ImGui::InputInt("Window (samples)",&windowSize_);ImGui::InputDouble("Maximum deviation from median",&threshold_);paragraph("Outliers become missing in a new column. Original measurements remain unchanged.");}if(utility_==4){ImGui::InputDouble("Gain",&gain_);ImGui::InputDouble("Offset",&offset_);paragraph("New column = original * gain + offset. This does not write instrument calibration.");}if(utility_==5){ImGui::InputDouble("Level interval",&step_);ImGui::InputDouble("Maximum interpolation gap",&maxGap_);paragraph("Select one monotonic downcast or upcast first. No extrapolation; large gaps stay missing.");}}
 ImGui::BeginDisabled(utility_==0&&!locationConfirmed_);if(button("Generate preview",ImVec2(185,32))){try{if(utility_==0){calc_.latitude=latitude_;calc_.longitude=longitude_;preview_=calculate(*t,calc_);}else if(utility_==1){if(rangeFirst_<1||rangeLast_<rangeFirst_||rangeLast_>static_cast<int>(t->rows.size()))throw std::runtime_error("Row selection is outside the dataset.");preview_=rangeRows(*t,rangeFirst_-1,rangeLast_);}else if(utility_==2){if(minimum_>maximum_)throw std::runtime_error("Minimum must not exceed maximum.");preview_=filterRange(*t,utilCol_,minimum_,maximum_);}else if(utility_==3)preview_=despike(*t,utilCol_,windowSize_,threshold_);else if(utility_==4)preview_=affine(*t,utilCol_,gain_,offset_);else preview_=standardDepths(*t,utilCol_,step_,maxGap_);preview_->source=t->source+" / derived";error_.clear();}catch(const std::exception& e){error_=e.what();preview_.reset();}}ImGui::EndDisabled();if(preview_){ImGui::SameLine();if(button("Keep as new dataset",ImVec2(200,32))){Table result=std::move(*preview_);preview_.reset();addDocument(std::move(result));page_=2;return;}ImGui::SameLine();if(button("Export preview"))saveData(preview_->csv(),L"Export derived measurements",L"csv");ImGui::Text("Preview: %zu rows, %zu columns",preview_->rows.size(),preview_->columns.size());grid(*preview_,std::max(120.f,ImGui::GetContentRegionAvail().y));}}
void App::drawLogger(){title("Logger files",heading_);muted("Copy measurements from the mounted logger disk to your computer.");paragraph("If the latest file is missing, stop logging on the instrument, request a disk refresh in Terminal, and wait for the disk to reappear. Copying here never deletes files from the logger.");ImGui::BeginDisabled(scanning_||copying_);if(button("Choose logger folder",ImVec2(210,34))){auto p=folderDialog(L"Select mounted logger disk or data folder");if(!p.empty()){disk_=p;diskFiles_.clear();diskSelected_.clear();}}ImGui::SameLine();if(button("Scan data files",ImVec2(170,34))&&!disk_.empty()){scanning_=true;auto root=disk_;scanner_=std::async(std::launch::async,[root]{std::vector<fs::path> files;std::error_code ec;for(fs::recursive_directory_iterator it(root,fs::directory_options::skip_permission_denied,ec),end;it!=end;it.increment(ec)){if(ec){ec.clear();continue;}if(it.depth()>5){it.disable_recursion_pending();continue;}if(it->is_symlink(ec)){it.disable_recursion_pending();continue;}auto ext=lower(it->path().extension().string());if(it->is_regular_file(ec)&&(ext==".txt"||ext==".csv"||ext==".log"||ext==".asc")){files.push_back(it->path());if(files.size()>=10000)break;}}std::sort(files.begin(),files.end());return files;});}ImGui::EndDisabled();if(!disk_.empty())paragraph(utf8(disk_).c_str());if(scanning_)muted("Scanning in background...");if(copying_)muted("Copying and verifying file sizes...");if(button("Select all"))std::fill(diskSelected_.begin(),diskSelected_.end(),true);ImGui::SameLine();if(button("Clear selection"))std::fill(diskSelected_.begin(),diskSelected_.end(),false);ImGui::SameLine();ImGui::BeginDisabled(copying_||scanning_||std::none_of(diskSelected_.begin(),diskSelected_.end(),[](bool b){return b;}));
 if(button("Copy selected files")){auto target=folderDialog(L"Select destination on your computer");if(!target.empty()){std::vector<fs::path> files;for(size_t i=0;i<diskFiles_.size();i++)if(diskSelected_[i])files.push_back(diskFiles_[i]);auto root=disk_;copying_=true;copier_=std::async(std::launch::async,[root,target,files]{size_t copied=0;for(auto& from:files){auto relative=fs::relative(from,root);if(relative.empty()||relative.is_absolute()||relative.string().find("..")!=std::string::npos)throw std::runtime_error("Unexpected source path.");auto to=target/relative;fs::create_directories(to.parent_path());if(fs::exists(to)){int suffix=1;auto base=to;do{to=base.parent_path()/(base.stem().wstring()+L"_copy"+std::to_wstring(suffix++)+base.extension().wstring());}while(fs::exists(to));}fs::copy_file(from,to,fs::copy_options::none);if(fs::file_size(from)!=fs::file_size(to))throw std::runtime_error("Copy verification failed: "+utf8(to));copied++;}return "Copied "+std::to_string(copied)+" files. Existing files were not overwritten.";});}}ImGui::EndDisabled();ImGui::BeginChild("files",ImVec2(0,0),ImGuiChildFlags_Borders);for(size_t i=0;i<diskFiles_.size();i++){ImGui::PushID(static_cast<int>(i));bool checked=diskSelected_[i];if(ImGui::Checkbox("##selected",&checked))diskSelected_[i]=checked;ImGui::SameLine();std::error_code ec;auto rel=fs::relative(diskFiles_[i],disk_,ec);if(ImGui::Selectable(utf8(ec?diskFiles_[i]:rel).c_str(),false,ImGuiSelectableFlags_AllowDoubleClick)&&ImGui::IsMouseDoubleClicked(0))loadFile(diskFiles_[i]);ImGui::PopID();}ImGui::EndChild();}
void App::drawAbout(){title("SAIV Instrument Studio",heading_);ImGui::Text("Version 0.2.0 | Independent Windows application");ImGui::Spacing();paragraph("Concept, specifications and application development: SAIV AS.");paragraph("Written in C++ with Dear ImGui and DirectX 11. Does not load or require the legacy SD200W executable.");ImGui::SeparatorText("INSTRUMENTS & FORMATS");paragraph("SAIV CTD / STD serial instruments, OSU107 instrument logger and SAIV110 Surface Logger. Menu-aware discovery, explicit wake/menu and download actions, full N rows, FIELDS compact logger files, and named delimited measurement tables.");ImGui::SeparatorText("DATA & CALCULATIONS");paragraph("Official TEOS-10 Gibbs SeaWater library: practical and absolute salinity, Conservative Temperature, density, sigma0, sound speed, depth and oxygen solubility. Exported derived datasets include units and assumptions.");ImGui::SeparatorText("DISCLAIMERS");paragraph("Always keep backup copies of your data files and verify measurement results before relying on them. Physical instrument acceptance testing is still required for this first release.");paragraph("This notice does not override any applicable contractual obligations or mandatory legal rights.");ImGui::SeparatorText("OPEN-SOURCE COMPONENTS");paragraph("Dear ImGui by Omar Cornut and contributors (MIT). Gibbs SeaWater Oceanographic Toolbox by SCOR/IAPSO WG127 and contributors. Full notices are supplied in THIRD_PARTY_NOTICES.md and the licenses folder.");ImGui::SeparatorText("DELIVERY SCOPE");paragraph("Instrument calibration programming, firmware updates, proprietary binary formats, GPS navigation, SMTP and specialised sonar exports are not implemented in this first release. See the supplied feature matrix for verified coverage.");}
void App::render(){
 poll();terminalFocused_=false;auto* v=ImGui::GetMainViewport();ImGui::SetNextWindowPos(v->WorkPos);ImGui::SetNextWindowSize(v->WorkSize);
 ImGui::Begin("SAIV Studio",nullptr,ImGuiWindowFlags_NoDecoration|ImGuiWindowFlags_NoMove|ImGuiWindowFlags_NoSavedSettings);
 const char* names[]={"Terminal","Graphs / data","Utilities","Logger files","About"};
 for(int i=0;i<5;i++){if(i)ImGui::SameLine();if(button(names[i])){page_=i+1;if(page_==1)focusTerminal_=true;}}
 ImGui::SameLine();if(button("Open file"))loadFile(fileDialog(false,L"Open measurements",L"txt",L"Measurements\0*.txt;*.csv;*.log;*.asc\0All files\0*.*\0\0"));
 ImGui::Separator();ImGui::BeginChild("content",ImVec2(0,-30));switch(page_){case 1:drawTerminal();break;case 2:drawData();break;case 3:drawUtilities();break;case 4:drawLogger();break;case 5:drawAbout();break;default:page_=1;break;}ImGui::EndChild();
 ImGui::Separator();ImGui::TextUnformatted(error_.empty()?notice_.c_str():error_.c_str());ImGui::End();
}
